<script setup lang="ts">
const {t}=useLocale();const s=useAtelier(),route=useRoute(),speed=ref(0),telemetry=ref({gear:1,rpm:900}),ready=ref(false),progress=ref(0),error=ref(''),cruise=ref(false),scene=ref<any>(),retry=ref(0)
s.select(String(route.params.car));s.environment.value='studio';const gear=computed(()=>telemetry.value.gear)
function auto(){cruise.value=!cruise.value;scene.value?.setKey('w',cruise.value)}
function resetDrive(){cruise.value=false;scene.value?.setKey('w',false);scene.value?.reset()}
onBeforeUnmount(()=>scene.value?.setKey('w',false))
</script>
<template><div class="drive-page"><AtelierHeader /><ClientOnly><VehicleScene ref="scene" :key="retry" drive @ready="ready=true" @progress="progress=$event" @speed="speed=$event" @telemetry="telemetry=$event" @error="error=$event" /></ClientOnly><div class="drive-title"><small>{{t('В ДВИЖЕНИИ','IN MOTION')}}</small><h2>{{s.car.value.brand}} {{s.car.value.name}}</h2></div><NuxtLink to="/" class="drive-exit outline">{{t('ВЫЙТИ','EXIT')}} ↗</NuxtLink><div v-if="!ready&&!error" class="drive-loading"><small>{{t('ПОДГОТОВКА СЦЕНЫ','PREPARING SCENE')}} / {{progress}}%</small></div><div v-if="error" class="error-panel"><p>{{t('Не удалось запустить сцену:','Scene could not initialize:')}} {{error}}</p><button class="outline" @click="error='';retry++">{{t('ПОВТОРИТЬ','RETRY')}}</button></div><div class="drive-hud"><strong>{{String(speed).padStart(3,'0')}}</strong><small>{{t('КМ/Ч','KM/H')}}</small><div class="rpm"><i :style="{width:Math.min(100,telemetry.rpm/8500*100)+'%'}"/></div><small>{{t('ПЕРЕДАЧА','GEAR')}} {{gear}}</small></div><div class="drive-controls"><div>W / ↑ {{t('ГАЗ','ACCELERATE')}} · S / ↓ {{t('ТОРМОЗ','BRAKE')}}<br>B {{t('НАЗАД','REVERSE')}} · SPACE {{t('ТОРМОЗ','BRAKE')}}<br>{{t('ПЕРЕТАСКИВАНИЕ — ОСМОТР','DRAG TO LOOK AROUND')}}<br>C {{t('КАМЕРА','CAMERA')}} · R {{t('СБРОС','RESET')}} · ESC {{t('ПАУЗА','PAUSE')}}</div><button :aria-pressed="cruise" @click="auto">{{cruise?t('ОСТАНОВИТЬ РАЗГОН','STOP ACCELERATING'):t('АВТОРАЗГОН','AUTO ACCELERATE')}}</button><button :aria-pressed="s.engine.value" @click="s.engine.value=!s.engine.value">{{s.engine.value?t('ВЫКЛЮЧИТЬ ЗВУК МОТОРА','MUTE ENGINE'):t('ЗВУК МОТОРА','ENGINE SOUND')}}</button><small v-if="s.car.value.shape===8" class="engine-credit"><a href="/audio/CREDITS.html" target="_blank" rel="noopener">{{t('Запись Ferrari 458 · источник','Ferrari 458 recording · source')}}</a></small><button @click="scene?.cycleCamera()">{{t('КАМЕРА','CAMERA')}}</button><button @click="resetDrive">{{t('СБРОС','RESET')}}</button></div></div></template>
